import { atom, read, update } from 'claude-code'
import type { Register, SessionRateLimit } from 'claude-code'

import type { Limits } from '../types'

const tick = atom({ plugin: 'everforest-zen', key: 'tick' } as const, 0)
const limits = atom({ plugin: 'everforest-zen', key: 'limits' } as const, null)
const files = atom({ plugin: 'everforest-zen', key: 'files' } as const, [])
const startedAt = atom({ plugin: 'everforest-zen', key: 'startedAt' } as const, null)
const agents = atom({ plugin: 'everforest-zen', key: 'agents' } as const, 0)
const activity = atom({ plugin: 'everforest-zen', key: 'activity' } as const, 0)
const turnStart = atom({ plugin: 'everforest-zen', key: 'turnStart' } as const, 0)
const lastBreath = atom({ plugin: 'everforest-zen', key: 'lastBreath' } as const, 0)
const restUntil = atom({ plugin: 'everforest-zen', key: 'restUntil' } as const, 0)
const bloomNoted = atom({ plugin: 'everforest-zen', key: 'bloomNoted' } as const, false)
const context = atom({ plugin: 'everforest-zen', key: 'context' } as const, null)

// settings, from the plugin's userConfig (see plugin.json); set in register
let NERD = true
let SOUND = true
let BLOOM_AT = 80
let BREATHE_EVERY = 50
let HIDE_IN_IDE = true
const REST_MS = 60_000

// the tree belongs to a plain terminal: inside a code editor (VS Code and its
// forks, JetBrains, Zed) it steps aside and leaves the editor's own look alone
let IN_IDE = false

const detectIde = (termProgram?: string, emulator?: string): boolean =>
  termProgram === 'vscode' || termProgram === 'zed' || (emulator ?? '').startsWith('JetBrains')

// draw the tree only on a real terminal, never in an editor's panel
const quiet = (surface: string) => HIDE_IN_IDE && (surface !== 'terminal' || IN_IDE)

// Everforest dark palette
const C = {
  far: '#3f5245',
  back: '#56705a',
  deep: '#4a6350',
  mid: '#7d9a6b',
  light: '#a7c080',
  aqua: '#83c092',
  trunk: '#7a6d5a',
  bark: '#9a8a70',
  grass: '#859289',
  fg: '#d3c6aa',
  yellow: '#dbbc7f',
  blue: '#7fbbb3',
  pink: '#d699b6',
  moss: '#b5b27a',
  brown: '#a68b5b',
  earth: '#8c6a4a',
  empty: '#4f585e',
  hint: '#7a8478',
  firefly: '#dbbc7f',
  glowLeaf: '#c9d9a0',
}

const ROWS = 8
const TW = 27
const GAP = 3

type Cell = { ch: string; color: string; glow?: boolean }
type Seg = { text: string; color: string }

const noise = (x: number, y: number, salt = 0) => {
  let n = Math.imul(x + 11, 73856093) ^ Math.imul(y + 7, 19349663) ^ Math.imul(salt + 3, 83492791)
  n = Math.imul(n ^ (n >>> 13), 1274126177)
  return ((n ^ (n >>> 16)) >>> 0) % 1000 / 1000
}

// 1 by day, 0.4 at night, ramping through dawn (5-8h) and dusk (18-21h)
const brightness = (h: number): number => {
  if (h >= 8 && h < 18) return 1
  if (h >= 18 && h < 21) return 1 - ((h - 18) / 3) * 0.6
  if (h >= 5 && h < 8) return 0.4 + ((h - 5) / 3) * 0.6
  return 0.4
}

// darken a colour toward the Everforest bg, so night stays green, only deeper
const dim = (hex: string, f: number): string => {
  if (f >= 1) return hex
  const bg = [43, 51, 57]
  const out = [1, 3, 5].map((i, k) => {
    const c = parseInt(hex.slice(i, i + 2), 16)
    return Math.round(bg[k]! + (c - bg[k]!) * f).toString(16).padStart(2, '0')
  })
  return `#${out.join('')}`
}

const put = (grid: Cell[][], row: number, col: number, ch: string, color: string, glow = false) => {
  if (row < 0 || row >= grid.length || col < 0 || col >= TW || ch === ' ') return
  grid[row]![col] = { ch, color, glow }
}

// shimmer: a stirred leaf takes the next shade
const STIR: Record<string, string> = { '@': '&', '#': '@', '%': '#', '&': '%' }

export type Mode = 'idle' | 'work' | 'agents' | 'web' | 'rest'

// the crown's three shades per mode: green at rest, cyan with company, blue on the web
// cherry blossom, in Everforest's own pink
const SAKURA: [string, string, string] = ['#e8b8cc', '#d699b6', '#a97a92']

const CROWN: Record<Mode, [string, string, string]> = {
  idle: ['#a7c080', '#7d9a6b', '#56705a'],
  work: ['#a7c080', '#7d9a6b', '#56705a'],
  agents: ['#83c092', '#5f9a84', '#3f6b5e'],
  web: ['#7fbbb3', '#5b8f8a', '#3e6466'],
  rest: ['#d8c48a', '#b5a46e', '#8f8158'],
}

/**
 * One detailed tree, always full. At rest it sways; while Claude works a band
 * of light sweeps through the crown; with subagents or on the web, a wave of
 * cyan or blue flows through the leaves.
 */
const tree = (t: number, mode: Mode, hour: number, workSecs: number, blooming: boolean): Cell[][] => {
  const grid: Cell[][] = Array.from({ length: ROWS }, () =>
    Array.from({ length: TW }, () => ({ ch: ' ', color: C.grass })),
  )
  const light = brightness(hour)
  const busy = mode !== 'idle'
  const fill = 0.97
  const cx = 13
  const cy = 2.1
  const rx = 12.2
  const ry = 2.75
  // once the context runs high the tree blooms: pink blossom among the green
  const green = CROWN.idle
  const tinted = CROWN[mode]

  for (let y = 0; y < 5; y++) {
    for (let x = 0; x < TW; x++) {
      const dx = (x - cx) / rx
      const dy = (y - cy) / ry
      const d = dx * dx + dy * dy
      if (d > 1) continue
      const edge = d > 0.78
      if (noise(x, y) > fill + (edge ? 0.04 : 0.1)) continue

      // which palette this leaf wears now: a diagonal wave drifting through the crown
      const inWave =
        ((mode === 'agents' || mode === 'web') && (((x + y * 2 - t) % 12) + 12) % 12 < 7) ||
        // time to rest: a slow warm wave, like late afternoon light
        (mode === 'rest' && (((x - y - Math.floor(t / 2)) % 10) + 10) % 10 < 6)
      const blossom = blooming && noise(x, y, 11) < 0.7
      const pal = inWave ? tinted : blossom ? SAKURA : green
      // while working, a soft band of light passes left to right
      const lit = mode === 'work' && (((x - t) % 18) + 18) % 18 < 3

      if (edge) {
        const side = Math.abs(dx) > 0.82
        const ch = side ? (dx < 0 ? '(' : ')') : dy < 0 ? (noise(x, y, 1) > 0.5 ? '.' : '-') : "'"
        put(grid, y, x, ch, lit ? C.glowLeaf : pal[0])
        continue
      }
      // light falls from the top left; leaves grow in clumps
      const clump = noise(Math.floor(x / 3), Math.floor(y / 2), 2)
      const shade = -0.6 * dx - 0.5 * dy + (clump - 0.5) * 0.9
      const [ch, color] = shade > -0.05 ? ['@', pal[0]] : shade > -0.5 ? ['#', pal[1]] : ['%', pal[2]]
      const stirred = (x + y * 5 + t) % (busy ? 3 : 11) === 0
      put(grid, y, x, stirred ? (STIR[ch] ?? ch) : ch, lit ? C.glowLeaf : color)
    }
  }

  // branches, trunk and roots
  const bark = C.trunk
  put(grid, 3, cx - 4, '\\', C.bark)
  put(grid, 3, cx + 4, '/', C.bark)
  put(grid, 4, cx - 2, '\\', C.bark)
  put(grid, 4, cx, '|', C.bark)
  put(grid, 4, cx + 2, '/', C.bark)
  put(grid, 5, cx - 1, '\\', bark)
  put(grid, 5, cx, '|', bark)
  put(grid, 5, cx + 1, '/', bark)
  put(grid, 6, cx - 1, '(', bark)
  put(grid, 6, cx, '|', bark)
  put(grid, 6, cx + 1, ')', bark)
  '_,/(|)\\,_'.split('').forEach((ch, i) => put(grid, 7, cx - 4 + i, ch, bark))

  // ground
  for (let x = 0; x < TW; x++) {
    if (grid[7]![x]!.ch !== ' ') continue
    const r = noise(x, 7, 5)
    put(grid, 7, x, r < 0.55 ? '~' : r < 0.78 ? ',' : r < 0.9 ? "'" : '"', r < 0.15 ? C.light : C.grass)
  }

  // a sprout grows at the roots while Claude works
  if (busy) {
    const sx = cx + 6
    const stage = workSecs < 3 ? 0 : workSecs < 8 ? 1 : workSecs < 15 ? 2 : 3
    const sprout = [[','], ['i'], ['|', 'Y'], ['|', 'Y', '.']][stage]!
    sprout.forEach((ch, i) => put(grid, 7 - i, sx, ch, i === 2 ? C.glowLeaf : C.light))
  }

  // sun or moon, and fireflies once the light goes
  const isDay = hour >= 6 && hour < 18
  put(grid, 0, TW - 1, isDay ? '*' : ')', C.yellow, true)
  if (light < 0.85) {
    for (let i = 0; i < 4; i++) {
      if ((t + i * 3) % 5 >= 3) continue
      const x = (i * 7 + 2 + Math.floor(t / 3) * (i % 2 === 0 ? 1 : -1) + TW * 8) % TW
      put(grid, 1 + ((i * 3 + Math.floor(t / 4)) % 5), x, '*', C.firefly, true)
    }
  }

  for (const row of grid) {
    for (const cell of row) {
      if (!cell.glow) cell.color = dim(cell.color, light)
    }
  }
  return grid
}

// merge neighbouring cells of one colour so a row is a handful of Text nodes
const runs = (row: Cell[]): Seg[] => {
  const out: Seg[] = []
  for (const cell of row) {
    const last = out[out.length - 1]
    if (last && last.color === cell.color) last.text += cell.ch
    else out.push({ text: cell.ch, color: cell.color })
  }
  return out
}

const toLimits = (rates: readonly SessionRateLimit[]): Limits | null => {
  const five = rates.find((r) => r.kind === 'five_hour')
  if (!five) return null
  const week = rates.find((r) => r.kind === 'seven_day')
  return { session: five.percentUsed, resetsAt: five.resetsAt ?? null, week: week ? week.percentUsed : null }
}

const left = (resetsAt: string | null, now: number): string => {
  if (!resetsAt) return ''
  const mins = Math.max(0, Math.round((Date.parse(resetsAt) - now) / 60000))
  const h = Math.floor(mins / 60)
  return h > 0 ? `${h}h ${mins % 60}m` : `${mins}m`
}

// green while there is plenty, turning to moss and then earth as it runs low
const tint = (pct: number) => (pct >= 90 ? C.earth : pct >= 75 ? C.brown : pct >= 50 ? C.moss : C.light)

// label colours fade from leaf green down to bark
const FADE = ['#a7c080', '#93ab76', '#7d9a6b', '#8f8a68', '#9a8a70'] as const

const ICON = { files: '\uf15b', context: '\uf2db', session: '\uf017', time: '\uf253', agents: '\uf1bb' }

const label = (name: keyof typeof ICON, color: string): Seg => ({
  text: `${NERD ? `${ICON[name]} ` : ''}${name.padEnd(8)}`,
  color,
})

const bar = (pct: number, width: number): Seg[] => {
  const filled = Math.round((Math.min(100, Math.max(0, pct)) / 100) * width)
  return [
    { text: '━'.repeat(filled), color: tint(pct) },
    { text: '─'.repeat(width - filled), color: C.empty },
  ]
}

const baseName = (path: string) => path.split('/').pop() ?? path

const clip = (segs: Seg[], width: number): Seg[] => {
  const out: Seg[] = []
  let room = width
  for (const s of segs) {
    if (room <= 0) break
    out.push(s.text.length > room ? { ...s, text: s.text.slice(0, room) } : s)
    room -= s.text.length
  }
  return out
}

type Facts = {
  lim: Limits | null
  recent: string[]
  ctx: number | null
  upMins: number | null
  running: number
  now: number
}

const span = (mins: number) => {
  const h = Math.floor(mins / 60)
  return h > 0 ? `${h}h ${mins % 60}m` : `${mins}m`
}

const info = (f: Facts, width: number): Seg[][] => {
  const barW = Math.max(4, Math.min(8, width - 26))
  const rows: Seg[][] = []

  const shown = f.recent.slice(0, 2).map(baseName)
  const more = f.recent.length - shown.length
  // a row shows only once it has something to say
  if (shown.length) {
    rows.push([
      label('files', FADE[0]),
      { text: shown.join(' · '), color: C.fg },
      ...(more > 0 ? [{ text: `  +${more}`, color: C.hint }] : []),
    ])
  }

  if (f.ctx !== null) {
    rows.push([label('context', FADE[1]), ...bar(f.ctx, barW), { text: ` ${Math.round(f.ctx)}%`, color: tint(f.ctx) }])
  }

  if (f.lim) {
    rows.push([
      label('session', FADE[2]),
      ...bar(f.lim.session, barW),
      { text: ` ${Math.round(f.lim.session)}%`, color: tint(f.lim.session) },
      { text: f.lim.resetsAt ? `  ${left(f.lim.resetsAt, f.now)}` : '', color: C.hint },
    ])
  }

  if (f.upMins !== null) rows.push([label('time', FADE[3]), { text: span(f.upMins), color: C.fg }])

  if (f.running > 0) rows.push([label('agents', FADE[4]), { text: String(f.running), color: C.fg }])
  return rows.map((r) => clip(r, width))
}

const WORDS = [
  'Breathing',
  'Rooting',
  'Sprouting',
  'Blooming',
  'Meditating',
  'Growing',
  'Listening',
  'Resting',
  'Flowing',
  'Unfolding',
  'Settling',
  'Drifting',
]

// bubbles either side of the words: a slow wave swells them in turn, mirrored,
// so the two sides rise and settle together
const BUBBLE = [' ', '.', '°', 'o', 'O'] as const
const BUBBLE_SHADE = ['#4a6350', '#56705a', '#6b8a62', '#7d9a6b', '#a7c080'] as const
const BUBBLES = 7

const bubbles = (t: number): { ch: string; color: string }[] =>
  Array.from({ length: BUBBLES }, (_, i) => {
    // i = 0 sits by the words; the swell travels outward
    const v = (Math.sin(t * 0.5 - i * 0.7) + 1) / 2
    const level = Math.min(BUBBLE.length - 1, Math.floor(v * BUBBLE.length))
    return { ch: BUBBLE[level]!, color: BUBBLE_SHADE[level]! }
  })

const hash = (s: string) => [...s].reduce((a, c) => (a * 31 + c.charCodeAt(0)) % 9973, 7)

export const register: Register = (on, options) => {
  NERD = options.nerdIcons !== false
  SOUND = options.sound !== false
  BLOOM_AT = typeof options.bloomAt === 'number' ? options.bloomAt : 80
  BREATHE_EVERY = typeof options.breatheEvery === 'number' ? options.breatheEvery : 50
  HIDE_IN_IDE = options.hideInIde !== false

  on('session.start', async ($, e, next) => {
    IN_IDE = detectIde(
      await $.env.get('TERM_PROGRAM'),
      await $.env.get('TERMINAL_EMULATOR'),
    )
    $.clock.every(700, () => {
      void update($, tick, (n) => n + 1)
    })
    // every so often, a gentle nudge to breathe: a toast, the wind, warm light in the crown
    $.clock.every(60_000, async () => {
      if (BREATHE_EVERY <= 0) return
      const now = await $.clock.now()
      const last = await read($, lastBreath)
      if (last === 0) {
        await update($, lastBreath, () => now)
        return
      }
      if (now - last < BREATHE_EVERY * 60_000) return
      await update($, lastBreath, () => now)
      await update($, restUntil, () => now + REST_MS)
      $.ui.toast('🌿 take a breath · stretch a little', { timeoutMs: 12_000 })
      if (SOUND) {
        const file = `${$.plugin.root}/sounds/wind.wav`
        void $.process
          .run(['pw-play', '--volume', '0.7', file])
          .then((r) => (r.exitCode === 0 ? r : $.process.run(['paplay', file])))
          .catch(() => undefined)
      }
    })
    $.clock.every(2000, async () => {
      const list = await $.agent.list()
      const running = list.filter((a) => a.status === 'running' || a.status === 'pending').length
      await update($, agents, () => running)
    })
    const usage = await $.session.usage()
    await update($, limits, () => toLimits(usage.rateLimits))
    await update($, context, () => usage.context.percent ?? null)
    await update($, startedAt, () => usage.startedAt)
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits')) await update($, limits, () => toLimits(e.rateLimits))
    if (e.changed.includes('context')) {
      const pct = e.context.percent ?? null
      await update($, context, () => pct)
      // one quiet word when the tree first blooms; again only after it settles
      const noted = await read($, bloomNoted)
      if (pct !== null && pct >= BLOOM_AT && !noted) {
        await update($, bloomNoted, () => true)
        $.ui.toast('🌸 the tree is in bloom · /compact when you are ready', { timeoutMs: 10_000 })
      } else if (pct !== null && pct < BLOOM_AT && noted) {
        await update($, bloomNoted, () => false)
      }
    }
    return next(e)
  })

  // web tools in flight: the tree turns blue while any runs
  on('tool.call', { tool: 'WebSearch' }, async ($, e, next) => {
    await update($, activity, (n) => n + 1)
    try {
      return await next(e)
    } finally {
      await update($, activity, (n) => Math.max(0, n - 1))
    }
  })

  on('tool.call', { tool: 'WebFetch' }, async ($, e, next) => {
    await update($, activity, (n) => n + 1)
    try {
      return await next(e)
    } finally {
      await update($, activity, (n) => Math.max(0, n - 1))
    }
  })

  on('tool.call', async ($, e, next) => {
    // bookkeeping only: it must never get in the way of the call
    try {
      if (e.tool === 'Edit' || e.tool === 'Write') {
        const path = e.file_path
        await update($, files, (list) => [path, ...list.filter((p) => p !== path)].slice(0, 20))
      }
    } catch {}
    return next(e)
  })

  // Claude is waiting on you: a permission prompt or a dialog. One soft call of a bird.
  on('classic.Notification', async ($, e, next) => {
    if (e.notification_type === 'permission_prompt' || e.notification_type === 'elicitation_dialog') {
      if (SOUND) {
        const file = `${$.plugin.root}/sounds/call.wav`
        void $.process
          .run(['pw-play', '--volume', '0.7', file])
          .then((r) => (r.exitCode === 0 ? r : $.process.run(['paplay', file])))
          .catch(() => undefined)
      }
    }
    return next(e)
  })

  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    if (SOUND) {
      const file = `${$.plugin.root}/sounds/call.wav`
      void $.process
        .run(['pw-play', '--volume', '0.7', file])
        .then((r) => (r.exitCode === 0 ? r : $.process.run(['paplay', file])))
        .catch(() => undefined)
    }
    return next(e)
  })

  // a soft gust of wind when a turn ends. The engine's own player is
  // macOS-only, so on Linux PipeWire plays the file; elsewhere it stays quiet.
  on('turn.complete', async ($, e, next) => {
    if (SOUND && e.agentId === undefined) {
      const file = `${$.plugin.root}/sounds/wind.wav`
      void $.process
        .run(['pw-play', '--volume', '0.7', file])
        .then((r) => (r.exitCode === 0 ? r : $.process.run(['paplay', file])))
        .catch(() => undefined)
    }
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    const now = await $.clock.now()
    await update($, turnStart, () => now)
    return next(e)
  })

  // the spinner line drawn in green, the words floating between two rows of bubbles
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    if (quiet(e.surface)) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const t = await read($, tick)
    const began = await read($, turnStart)
    const secs = began ? Math.max(0, Math.round(((await $.clock.now()) - began) / 1000)) : 0
    const word = e.props.message ?? WORDS[hash(e.props.word) % WORDS.length] ?? WORDS[0]!
    const side = bubbles(t)
    const left = [...side].reverse()
    return (
      <Box>
        {left.map((b, i) => (
          <Text key={`l${i}`} color={b.color}>
            {b.ch}
          </Text>
        ))}
        <Text color={C.mid}> {word} </Text>
        {side.map((b, i) => (
          <Text key={`r${i}`} color={b.color}>
            {b.ch}
          </Text>
        ))}
        <Text color={C.hint}> ({secs < 60 ? `${secs}s` : `${Math.floor(secs / 60)}m ${secs % 60}s`})</Text>
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || quiet(e.surface)) return next(e)

    const t = await read($, tick)
    const now = await $.clock.now()
    const lim = await read($, limits)
    const began = await read($, startedAt)
    const facts: Facts = {
      lim,
      recent: await read($, files),
      ctx: await read($, context),
      running: await read($, agents),
      upMins: began === null ? null : Math.max(0, Math.round((now - began) / 60000)),
      now,
    }
    const clock = new Date(now)
    const web = await read($, activity)
    const resting = now < (await read($, restUntil))
    const mode: Mode = resting ? 'rest' : web > 0 ? 'web' : facts.running > 0 ? 'agents' : e.props.isWorking ? 'work' : 'idle'
    const began2 = await read($, turnStart)
    const workSecs = began2 ? (now - began2) / 1000 : 0
    const grid = tree(t, mode, clock.getHours() + clock.getMinutes() / 60, workSecs, (facts.ctx ?? 0) >= BLOOM_AT)
    const infoWidth = Math.max(0, Math.min(e.props.bodyColumns, 100) - TW - GAP)
    const side = info(facts, infoWidth)
    const top = Math.max(0, Math.floor((ROWS - side.length) / 2))
    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="column">
        {grid.map((row, y) => (
          <Box key={`r${y}`}>
            {runs(row).map((seg, i) => (
              <Text key={`t${i}`} color={seg.color}>
                {seg.text}
              </Text>
            ))}
            {infoWidth > 0 && side[y - top] ? <Text>{' '.repeat(GAP)}</Text> : null}
            {(side[y - top] ?? []).map((seg, i) => (
              <Text key={`i${i}`} color={seg.color}>
                {seg.text}
              </Text>
            ))}
          </Box>
        ))}
      </Box>
    )
  })
}

